<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>学途 - 在线学习平台</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #1a202c; line-height: 1.6; background: #fff; }
        a { text-decoration: none; color: inherit; }
        img { max-width: 100%; }

        /* Nav */
        .nav { position: sticky; top: 0; z-index: 100; background: #fff; border-bottom: 1px solid #e2e8f0; padding: 0 40px; height: 64px; display: flex; align-items: center; justify-content: space-between; }
        .nav-logo { font-size: 24px; font-weight: 700; color: #1e40af; }
        .nav-logo span { color: #f59e0b; }
        .nav-links { display: flex; gap: 32px; align-items: center; }
        .nav-links a { font-size: 15px; color: #4a5568; transition: color .2s; }
        .nav-links a:hover { color: #1e40af; }
        .nav-cta { background: #1e40af; color: #fff !important; padding: 8px 20px; border-radius: 6px; font-weight: 500; }
        .nav-cta:hover { background: #1e3a8a; }

        /* Hero */
        .hero { background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 60%, #60a5fa 100%); padding: 100px 40px; text-align: center; color: #fff; }
        .hero h1 { font-size: 48px; font-weight: 800; margin-bottom: 16px; letter-spacing: -0.5px; }
        .hero p { font-size: 20px; opacity: .9; max-width: 640px; margin: 0 auto 32px; }
        .hero-btn { display: inline-block; background: #f59e0b; color: #1a202c; font-size: 17px; font-weight: 600; padding: 14px 36px; border-radius: 8px; transition: transform .2s, box-shadow .2s; }
        .hero-btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.2); }
        .hero-sub { margin-top: 16px; font-size: 14px; opacity: .7; }

        /* Stats */
        .stats { display: flex; justify-content: center; gap: 80px; padding: 60px 40px; background: #f8fafc; border-bottom: 1px solid #e2e8f0; flex-wrap: wrap; }
        .stat-item { text-align: center; }
        .stat-num { font-size: 36px; font-weight: 800; color: #1e40af; }
        .stat-label { font-size: 14px; color: #64748b; margin-top: 4px; }

        /* Section */
        .section { padding: 80px 40px; max-width: 1200px; margin: 0 auto; }
        .section-title { font-size: 32px; font-weight: 700; text-align: center; margin-bottom: 12px; }
        .section-sub { text-align: center; color: #64748b; margin-bottom: 48px; font-size: 16px; }

        /* Category Grid */
        .cat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
        .cat-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 32px; text-align: center; transition: box-shadow .2s, transform .2s; cursor: pointer; }
        .cat-card:hover { box-shadow: 0 12px 32px rgba(30,64,175,.1); transform: translateY(-4px); }
        .cat-icon { font-size: 40px; margin-bottom: 16px; }
        .cat-card h3 { font-size: 18px; margin-bottom: 8px; }
        .cat-card p { font-size: 14px; color: #64748b; }

        /* Course Cards */
        .course-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
        .course-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; transition: box-shadow .2s, transform .2s; }
        .course-card:hover { box-shadow: 0 12px 32px rgba(0,0,0,.08); transform: translateY(-3px); }
        .course-thumb { height: 160px; display: flex; align-items: center; justify-content: center; font-size: 48px; }
        .course-thumb.lang { background: linear-gradient(135deg, #dbeafe, #eff6ff); }
        .course-thumb.dev { background: linear-gradient(135deg, #dcfce7, #f0fdf4); }
        .course-thumb.exam { background: linear-gradient(135deg, #fef3c7, #fffbeb); }
        .course-body { padding: 20px; }
        .course-tag { display: inline-block; font-size: 12px; padding: 3px 10px; border-radius: 20px; margin-bottom: 10px; font-weight: 500; }
        .tag-lang { background: #dbeafe; color: #1e40af; }
        .tag-dev { background: #dcfce7; color: #166534; }
        .tag-exam { background: #fef3c7; color: #92400e; }
        .course-card h3 { font-size: 16px; margin-bottom: 8px; }
        .course-meta { font-size: 13px; color: #64748b; margin-bottom: 12px; }
        .course-bottom { display: flex; justify-content: space-between; align-items: center; }
        .price { font-size: 18px; font-weight: 700; color: #1e40af; }
        .price small { font-size: 12px; color: #94a3b8; font-weight: 400; text-decoration: line-through; margin-left: 6px; }
        .enroll-btn { font-size: 13px; background: #1e40af; color: #fff; padding: 6px 16px; border-radius: 6px; font-weight: 500; }
        .enroll-btn:hover { background: #1e3a8a; }

        /* Testimonials */
        .testimonials { background: #f8fafc; padding: 80px 40px; }
        .testi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1200px; margin: 0 auto; }
        .testi-card { background: #fff; border-radius: 12px; padding: 28px; border: 1px solid #e2e8f0; }
        .testi-text { font-size: 14px; color: #4a5568; margin-bottom: 16px; line-height: 1.7; }
        .testi-author { display: flex; align-items: center; gap: 12px; }
        .testi-avatar { width: 40px; height: 40px; border-radius: 50%; background: #dbeafe; display: flex; align-items: center; justify-content: center; font-size: 16px; font-weight: 600; color: #1e40af; }
        .testi-name { font-size: 14px; font-weight: 600; }
        .testi-role { font-size: 12px; color: #94a3b8; }

        /* CTA Banner */
        .cta-banner { background: linear-gradient(135deg, #1e3a8a, #3b82f6); padding: 72px 40px; text-align: center; color: #fff; }
        .cta-banner h2 { font-size: 32px; margin-bottom: 12px; }
        .cta-banner p { opacity: .85; margin-bottom: 28px; font-size: 16px; }
        .cta-banner .hero-btn { font-size: 16px; }

        /* Footer */
        .footer { background: #0f172a; color: #94a3b8; padding: 60px 40px 32px; }
        .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; max-width: 1200px; margin: 0 auto 40px; }
        .footer h4 { color: #fff; font-size: 14px; margin-bottom: 16px; }
        .footer a { display: block; font-size: 13px; color: #94a3b8; margin-bottom: 10px; transition: color .2s; }
        .footer a:hover { color: #fff; }
        .footer-brand p { font-size: 13px; line-height: 1.7; margin-top: 8px; }
        .footer-bottom { border-top: 1px solid #1e293b; padding-top: 24px; text-align: center; font-size: 12px; max-width: 1200px; margin: 0 auto; }

        /* Responsive */
        @media (max-width: 900px) {
            .cat-grid, .course-grid, .testi-grid { grid-template-columns: 1fr; }
            .stats { gap: 40px; }
            .hero h1 { font-size: 32px; }
            .nav { padding: 0 20px; }
            .nav-links { gap: 16px; }
            .footer-grid { grid-template-columns: 1fr 1fr; }
            .section { padding: 50px 20px; }
        }
        @media (max-width: 600px) {
            .nav-links a:not(.nav-cta) { display: none; }
            .stats { flex-direction: column; gap: 24px; }
            .footer-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>
